const orgSecurityOverviewSummary = `-- name: OrgSecurityOverviewSummary :one
WITH org_repos AS (
    SELECT id
    FROM repos
    WHERE owner_org_id = $1
      AND deleted_at IS NULL
),
current_deps AS (
    SELECT d.id, d.repo_id, d.ecosystem, d.package_name, d.package_version, d.manifest_path, d.lockfile_path, d.scope, d.direct, d.package_manager, d.source, d.last_seen_sha, d.first_seen_at, d.last_seen_at, d.stale_at
    FROM repo_dependencies d
    JOIN org_repos r ON r.id = d.repo_id
    WHERE d.stale_at IS NULL
),
open_alerts AS (
    SELECT alert.id, alert.repo_id, alert.dependency_id, alert.advisory_id, alert.status, alert.dismissal_note, alert.dismissed_by, alert.dismissed_at, alert.resolved_at, alert.first_seen_at, alert.last_seen_at, a.severity
    FROM repo_dependency_alerts alert
    JOIN dependency_advisories a ON a.id = alert.advisory_id
    JOIN current_deps d ON d.id = alert.dependency_id
    WHERE alert.status = 'open'
),
repo_advisories AS (
    SELECT rsa.id, rsa.repo_id, rsa.identifier, rsa.state, rsa.severity, rsa.summary, rsa.description, rsa.affected_ecosystem, rsa.affected_package, rsa.vulnerable_versions, rsa.patched_versions, rsa.created_by, rsa.published_at, rsa.closed_at, rsa.created_at, rsa.updated_at, rsa.ghsa_id, rsa.cve_id, rsa.reference_urls, rsa.withdrawn_at, rsa.archived_at
    FROM repo_security_advisories rsa
    JOIN org_repos r ON r.id = rsa.repo_id
    WHERE rsa.state IN ('draft', 'published')
)
SELECT
    (SELECT count(*) FROM org_repos) AS repo_count,
    (SELECT count(*) FROM current_deps) AS dependency_count,
    (SELECT count(DISTINCT manifest_path) FROM current_deps) AS manifest_count,
    (SELECT count(*) FROM open_alerts) AS open_alert_count,
    (SELECT count(*) FROM open_alerts WHERE severity = 'critical') AS critical_alert_count,
    (SELECT count(*) FROM open_alerts WHERE severity = 'high') AS high_alert_count,
    (SELECT count(*) FROM open_alerts WHERE severity = 'moderate') AS moderate_alert_count,
    (SELECT count(*) FROM repo_advisories) AS repository_advisory_count
`

type OrgSecurityOverviewSummaryRow struct {
	RepoCount               int64
	DependencyCount         int64
	ManifestCount           int64
	OpenAlertCount          int64
	CriticalAlertCount      int64
	HighAlertCount          int64
	ModerateAlertCount      int64
	RepositoryAdvisoryCount int64
}

